#!/bin/bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"

# Train Faster R-CNN on UIIS10K easy_merged and evaluate on the same easy_merged.
# UIIS10K is originally an instance segmentation dataset; this script uses the
# bbox-only detection COCO generated by tools/convert_uiis10k_seg_to_det.py and
# tools/uiis10k_cross_easy.py.
#
# This is a self-eval sanity check for the selected UIIS easy subset, not a
# generalization test.

cd "$REPO_ROOT"

UIIS_ROOT="${UIIS_ROOT:-/media/HDD0/XCX/exp_2/UIIS10K}"
EASY_ANN="${EASY_ANN:-$UIIS_ROOT/coco/annotations/cross_split_det/easy_merged.json}"
GPU_IDS="${GPU_IDS:-2,3}"
NUM_GPUS="${NUM_GPUS:-2}"
PORT="${PORT:-29830}"
MAX_EPOCHS="${MAX_EPOCHS:-96}"
MILESTONES="${MILESTONES:-[64,88]}"
BATCH_SIZE="${BATCH_SIZE:-4}"
NUM_WORKERS="${NUM_WORKERS:-2}"
WORK_DIR="${WORK_DIR:-work_dirs/uiis_easy_faster_rcnn_self_eval_e96}"
LOG_DIR="${LOG_DIR:-logs}"
LOG_FILE="${LOG_FILE:-$LOG_DIR/uiis_easy_faster_rcnn_self_eval_e96.log}"
MAX_KEEP_CKPTS="${MAX_KEEP_CKPTS:-5}"

CLASSES="('holothurian','echinus','scallop','starfish','fish','corals','diver','cuttlefish','turtle','jellyfish')"

mkdir -p "$LOG_DIR" "$WORK_DIR"

if [ ! -f "$EASY_ANN" ]; then
    echo "Error: UIIS easy annotation not found: $EASY_ANN"
    echo "Run first:"
    echo "  bash scripts/exp_2/uiis/run_exp_2_uiis_easy_j10_full.sh"
    exit 1
fi

if [ ! -d "$UIIS_ROOT/img" ]; then
    echo "Error: UIIS image directory not found: $UIIS_ROOT/img"
    exit 1
fi

echo "========================================="
echo "UIIS easy Faster R-CNN self-eval"
echo "========================================="
echo "UIIS_ROOT: $UIIS_ROOT"
echo "EASY_ANN: $EASY_ANN"
echo "GPU_IDS: $GPU_IDS"
echo "NUM_GPUS: $NUM_GPUS"
echo "PORT: $PORT"
echo "MAX_EPOCHS: $MAX_EPOCHS"
echo "MILESTONES: $MILESTONES"
echo "BATCH_SIZE: $BATCH_SIZE"
echo "WORK_DIR: $WORK_DIR"
echo "LOG_FILE: $LOG_FILE"
echo "========================================="

export PORT
export MKL_THREADING_LAYER="${MKL_THREADING_LAYER:-GNU}"

CUDA_VISIBLE_DEVICES="$GPU_IDS" bash tools/dist_train.sh \
    configs/faster_rcnn/faster-rcnn_r50_fpn_1x_coco.py \
    "$NUM_GPUS" \
    --work-dir "$WORK_DIR" \
    --cfg-options \
        model.roi_head.bbox_head.num_classes=10 \
        train_dataloader.batch_size="$BATCH_SIZE" \
        train_dataloader.num_workers="$NUM_WORKERS" \
        train_dataloader.dataset.type=CocoDataset \
        train_dataloader.dataset.data_root="$UIIS_ROOT/" \
        train_dataloader.dataset.ann_file=coco/annotations/cross_split_det/easy_merged.json \
        train_dataloader.dataset.data_prefix.img=img/ \
        train_dataloader.dataset.metainfo.classes="$CLASSES" \
        val_dataloader.batch_size=1 \
        val_dataloader.num_workers="$NUM_WORKERS" \
        val_dataloader.dataset.type=CocoDataset \
        val_dataloader.dataset.data_root="$UIIS_ROOT/" \
        val_dataloader.dataset.ann_file=coco/annotations/cross_split_det/easy_merged.json \
        val_dataloader.dataset.data_prefix.img=img/ \
        val_dataloader.dataset.metainfo.classes="$CLASSES" \
        test_dataloader.dataset.type=CocoDataset \
        test_dataloader.dataset.data_root="$UIIS_ROOT/" \
        test_dataloader.dataset.ann_file=coco/annotations/cross_split_det/easy_merged.json \
        test_dataloader.dataset.data_prefix.img=img/ \
        test_dataloader.dataset.metainfo.classes="$CLASSES" \
        val_evaluator.ann_file="$EASY_ANN" \
        test_evaluator.ann_file="$EASY_ANN" \
        val_evaluator.metric=bbox \
        test_evaluator.metric=bbox \
        train_cfg.max_epochs="$MAX_EPOCHS" \
        param_scheduler.1.end="$MAX_EPOCHS" \
        param_scheduler.1.milestones="$MILESTONES" \
        default_hooks.checkpoint.save_best=coco/bbox_mAP \
        default_hooks.checkpoint.max_keep_ckpts="$MAX_KEEP_CKPTS" \
    2>&1 | tee "$LOG_FILE"

echo "========================================="
echo "Best / latest UIIS easy self-eval mAP"
echo "========================================="
grep -a "coco/bbox_mAP:" "$LOG_FILE" | \
    sed -E 's/.*Epoch\(val\) \[([0-9]+)\].*coco\/bbox_mAP: ([0-9.]+).*coco\/bbox_mAP_50: ([0-9.]+).*coco\/bbox_mAP_75: ([0-9.]+).*/epoch_\1 mAP=\2 AP50=\3 AP75=\4/' | \
    sort -t= -k2 -nr | head -n 10 || true

echo "========================================="
echo "Checkpoints"
echo "========================================="
ls -lh "$WORK_DIR"/best_coco_bbox_mAP*.pth 2>/dev/null || true
